package main

import (
    "errors"
    "fmt"
)

var ErrEmpty = errors.New("empty name")

func greet(name string) (string, error) {
    if name == "" {
        return "", ErrEmpty
    }
    if len(name) < 3 {
        return "", fmt.Errorf("name too short: %s", name)
    }
    return "Hello, " + name, nil
}

func main() {
    result, err := greet("Firdavs")
    if err != nil {
        fmt.Println("Error:", err)
    } else {
        fmt.Println(result)
    }

    _, err = greet("")
    if errors.Is(err, ErrEmpty) {
        fmt.Println("rejected: empty")
    }

    _, err = greet("Al")
    if err != nil {
        fmt.Println("Error:", err)
    }
}

