package main

import "fmt"

type Todo struct {
    Title string
    Done  bool
}

func add(list []Todo, title string) []Todo {
    return append(list, Todo{Title: title})
}

func complete(list []Todo, index int) {
    if index >= 0 && index < len(list) {
        list[index].Done = true
    }
}

func report(list []Todo) (done int, pending int) {
    for _, item := range list {
        if item.Done {
            done++
        } else {
            pending++
        }
    }
    return done, pending
}

func main() {
    todos := []Todo{}
    todos = add(todos, "learn Go basics")
    todos = add(todos, "practice slices")
    todos = add(todos, "write first test")

    complete(todos, 0)
    complete(todos, 2)

    for i, item := range todos {
        mark := "[ ]"
        if item.Done {
            mark = "[x]"
        }
        fmt.Println(i+1, mark, item.Title)
    }

    done, pending := report(todos)
    fmt.Println("done:", done, "pending:", pending)

    if pending == 0 {
        fmt.Println("All tasks complete")
    } else {
        fmt.Println("Keep going!")
    }
}

